def forward(groups):
    value = float(groups[0])
    unit = groups[1].lower()
    multiplier = 1 if unit == 'b' else (1024 if unit == 'kb' else 1024 * 1024)
    return {'stored': [int(round(value * multiplier))], 'layout': [unit]}

def inverse(record):
    value = record['stored'][0]
    unit = record['layout'][0]
    if unit == 'kb':
        display_value = value / 1024
        unit = 'KB'
    elif unit == 'mb':
        display_value = value / (1024 * 1024)
        unit = 'MB'
    else:
        display_value = value
        unit = 'B'
    return f'(estimated size {display_value:.1f} {unit})'
